function fixture() {
  const world = new World();
  const roles = [
    Role.EclipseMaid,
    Role.RadiantCount,
    Role.Seer,
    Role.Witch,
    Role.Dreamer,
    Role.Villager,
    Role.Villager,
    Role.Villager,
    Role.Villager,
    Role.Wolf,
    Role.Wolf,
    Role.Wolf,
  ];
  for (const kind of roles) {
    const id = world.createEntity(),
      camp = kind === Role.EclipseMaid || kind === Role.Wolf ? Camp.Wolf : Camp.Good,
      role = createRoleComponent(kind, camp);
    world.addComponent(id, COMPONENT.Role, role);
    world.addComponent(id, COMPONENT.Camp, createCampComponent(camp));
    world.addComponent(
      id,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: camp }]),
    );
    world.addComponent(id, COMPONENT.Alive, createAliveComponent());
    world.addComponent(id, COMPONENT.Identity, {
      id,
      seat: id,
      name: `synthetic-${id}`,
      sessionId: "synthetic",
    });
    if (kind === Role.EclipseMaid) {
      (role.privateState as Record<string, unknown>).eclipse = createEclipseState();
      (role.privateState as Record<string, unknown>).abilities = {};
    }
    if (kind === Role.RadiantCount) installNativeAbility(role, "shelter", createShelterState());
    if (kind === Role.Seer)
      installNativeAbility(role, "seer_check", {
        lastTarget: null,
        lastIsWerewolf: null,
        history: [],
      });
    if (kind === Role.Witch)
      installNativeAbility(role, "potion", {
        heal: 1,
        poison: 0,
        selfHealRule: WitchSelfHealRule.Disabled,
        canSelfHeal: false,
        healUsedThisNight: false,
        poisonUsedThisNight: false,
      });
    if (kind === Role.Dreamer)
      installNativeAbility(role, "dream", {
        lastTarget: 6,
        lastDay: 1,
        history: [{ day: 1, targetId: 6 }],
        protectionPolicy: "netease_2026_night_immunity_v1",
      });
  }
  const role = (id: number) => world.getComponent(id, COMPONENT.Role)!;
  const events: GameEvent[] = [];
  installRadiantEclipseBoard(world);
  return { world, role, events };
}

class Stages extends NightStageRegistry {
  override getStages() {
    return [ECLIPSE_SWALLOW_STAGE, DREAMER_NIGHT_STAGE];
  }
}

// 配置经真实公开板子解析，带齐阵容、警长与固定政策，满足现有有限准入。
// 场景仍固定原玩家与已付库存历史，不从通用模拟器重新生成动作或断言。
const config = parseBoardDefinition(
  JSON.parse(
    readFileSync(
      new URL("../../../../../configs.example/boards/awa_radiant_eclipse_12_v1.json", import.meta.url),
      "utf8",
    ),
  ),
).config;

const provider: ActionProvider = {
  getAction: async (request) => {
    if (request.context.stage === "eclipse_swallow")
      return { name: "swallow_skill", args: { target_id: 5 } };
    if (request.context.stage === "dreamer") return { name: "dream", args: { target_id: 7 } };
    throw new Error("unexpected_request");
  },
};

for (const dead of [1, 5])
  test(`paid borrowed Dream after committed close follows actual caster ${dead}`, async () => {
    const f = fixture();
    class DamageStages extends Stages {
      override getStages() {
        return [
          ...super.getStages(),
          {
            id: "synthetic_attack",
            priority: 999,
            async execute(ctx: any) {
              ctx.ensureMarks(dead).add(StatusMark.PoisonMark);
            },
          },
        ];
      }
    }
    const result = await new NightPipeline({
      world: f.world,
      toolGateway: new ToolGateway(),
      damageResolutionSystem: new DamageResolutionSystem(),
      events: f.events,
      stageRegistry: new DamageStages(),
    }).execute(config, provider, 2);
    expect(result.interrupted).toBe(false);
    if (result.interrupted) throw new Error("unexpected_interrupt");
    expect(result.damage.deaths).toEqual(dead === 1 ? [1, 7] : [5]);
    expect(result.damage.deathSources).toEqual(
      dead === 1 ? { 1: [DeathCause.Poison], 7: [DeathCause.Dream] } : { 5: [DeathCause.Poison] },
    );
    const borrowed = findNightAbility(f.role(1), "dream")!,
      native = findNightAbility(f.role(5), "dream")!;
    expect(borrowed.disabled).toBe(true);
    expect(native.nightSuppression).toBeUndefined();
    expect(native.state).toEqual({
      lastTarget: 6,
      lastDay: 1,
      history: [{ day: 1, targetId: 6 }],
      protectionPolicy: "netease_2026_night_immunity_v1",
    });
    expect(result.dreamFrame.protectedTargets(f.world)).toEqual([7]);
    const life = f.world.getComponent(dead, COMPONENT.Alive)!;
    life.alive = false;
    expect(result.dreamFrame.linkedDeaths(f.world, [dead])).toEqual(dead === 1 ? [7] : []);
    expect(
      f.events.filter((e) => e.type === "eclipse_lease_closed").map((e) => e.payload.status),
    ).toEqual(["committed"]);
    expect(
      f.events.filter((e) => e.type === "eclipse_native_restored").map((e) => e.payload.playerId),
    ).toEqual([5]);
  });

test("actual later-stage failure retains paid Dream fact and stock but revokes handed-out effect", async () => {
  const f = fixture();
  let links: readonly DreamNightLink[] = [];
  class FailStages extends Stages {
    override getStages() {
      return [
        ...super.getStages(),
        {
          id: "synthetic_failure",
          priority: 999,
          async execute(ctx: any) {
            links = readDreamNightLinks(ctx.state);
            throw new Error("synthetic_after_payment");
          },
        },
      ];
    }
  }
  await expect(
    new NightPipeline({
      world: f.world,
      toolGateway: new ToolGateway(),
      damageResolutionSystem: new DamageResolutionSystem(),
      events: f.events,
      stageRegistry: new FailStages(),
    }).execute(config, provider, 2),
  ).rejects.toThrow("synthetic_after_payment");
  const borrowed = findNightAbility(f.role(1), "dream")!,
    native = findNightAbility(f.role(5), "dream")!,
    frame = new DreamNightFrame(links);
  expect(borrowed.disabled).toBe(true);
  expect(native.nightSuppression).toBeUndefined();
  expect(borrowed.uses).toBe(1);
  expect(borrowed.state.history).toEqual([{ day: 2, targetId: 7 }]);
  expect(frame.protectedTargets(f.world)).toEqual([]);
  expect(frame.linkedDeaths(f.world, [1])).toEqual([]);
  expect(f.events.filter((e) => e.type === "dream_applied").map((e) => e.payload)).toEqual([
    { actorId: 1, targetId: 7, day: 2, consecutive: false, abilityId: borrowed.id },
  ]);
  expect(
    f.events.filter((e) => e.type === "eclipse_lease_closed").map((e) => e.payload.status),
  ).toEqual(["aborted"]);
  expect(
    f.events.filter((e) =>
      ["eclipse_native_restored", "night_resolved", "game_over"].includes(e.type),
    ),
  ).toEqual([]);
});

/**
 * 编译期单元负责蚀日侍女／匿名留言纯数据迁移的原形状、可写性和类型入口验证。
 * 输入为独立手写旧字段、union／nullable 与 World 具名入口；输出为精确关系和错误字段反例。
 * 本单元拥有独立预期，不运行 reader、World、吞噬、借用或写信；知识 ID 与有效余量不授予许可。
 */
import type {
  EclipseState,
  EclipseSwallowedRole,
} from "@ai-werewolf-arena/game-contract/facts/radiant-eclipse";
import type {
  WallNoteComponent,
  readWallNoteData,
} from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import type { PlayerObservation } from "../../../src/game/observation/player-observation";
import type { WallNoteComponent as WorldWallNote } from "../../../src/core/domain/components/wall_note";
import type { projectEclipseState } from "../../../src/game/mechanisms/roles/radiant_eclipse/state";
import type {
  // @ts-expect-error 原 feature type 出口退休，runtime 规则／投影仍保留。
  EclipseState as RetiredState,
  // @ts-expect-error 纯五角色联合归 GC；原 runtime goodRoles 不迁或开放。
  EclipseSwallowedRole as RetiredRole,
} from "../../../src/game/mechanisms/roles/radiant_eclipse/state";
export type RetiredFeatureChecks = [RetiredState, RetiredRole];

type OriginalSwallowedRole = "villager" | "seer" | "witch" | "dreamer" | "radiant_count";
interface OriginalEclipse {
  policy: "awa_radiant_eclipse_v1";
  history: Array<{
    day: number;
    targetId: number | null;
    roleId: OriginalSwallowedRole | null;
    abilityId: string | null;
  }>;
}
interface OriginalWall {
  instanceId: string;
  source: { kind: "wall_event"; eventId: "awa_wall_notes_v1"; day: 1 };
  remaining: 0 | 1;
  expired: boolean;
}
type OriginalPlayerWall = OriginalWall & { effectiveRemaining: 0 | 1 };
type Equal<A, B> =
  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Expect<T extends true> = T;
export type PublicShapeChecks = [
  Expect<Equal<EclipseSwallowedRole, OriginalSwallowedRole>>,
  Expect<Equal<EclipseState, OriginalEclipse>>,
  Expect<Equal<WallNoteComponent, OriginalWall>>,
  Expect<Equal<WorldWallNote, OriginalWall>>,
  Expect<Equal<ReturnType<typeof projectEclipseState>, OriginalEclipse | undefined>>,
  Expect<Equal<ReturnType<typeof readWallNoteData>, OriginalWall | null>>,
  Expect<Equal<PlayerObservation["ownState"]["eclipse"], OriginalEclipse | undefined>>,
  Expect<Equal<PlayerObservation["ownState"]["wallNote"], OriginalPlayerWall | undefined>>,
  Expect<EclipseState extends OriginalEclipse ? true : false>,
  Expect<OriginalEclipse extends EclipseState ? true : false>,
  Expect<WallNoteComponent extends OriginalWall ? true : false>,
  Expect<OriginalWall extends WallNoteComponent ? true : false>,
];

/** 仅编译原 nested 可写／null／literal；不写实际原体或对局库存。 */
export function originalWritableData(
  eclipse: EclipseState,
  wall: WallNoteComponent,
  playerWall: OriginalPlayerWall,
): void {
  eclipse.history = [{ day: 2, targetId: null, roleId: null, abilityId: null }];
  eclipse.history.push({ day: 3, targetId: 4, roleId: "seer", abilityId: "copy:eclipse:night:3" });
  eclipse.history[0]!.targetId = 2;
  eclipse.history[0]!.roleId = "villager";
  eclipse.history[0]!.abilityId = null;
  wall.instanceId = "wall:1:2";
  wall.source = { kind: "wall_event", eventId: "awa_wall_notes_v1", day: 1 };
  wall.source.day = 1;
  wall.remaining = 0;
  wall.expired = true;
  playerWall.effectiveRemaining = 1;
  // @ts-expect-error 公开history无live ability payload或租约。
  eclipse.lease;
  // @ts-expect-error 有限角色联合不包括普通狼人。
  eclipse.history[0]!.roleId = "wolf";
  // @ts-expect-error 原source严格首日literal，不扩为任意日次。
  wall.source.day = 2;
  // @ts-expect-error 原库存类型是0或1。
  wall.remaining = 2;
  // @ts-expect-error 玩家有效余量仍有原字段与0或1边界。
  playerWall.effectiveRemaining = 2;
}

