/**
 * 输入为未知数据与精确字段列表；输出为只含原 data descriptor 值的新记录、正整数判定或无效结果。
 * 明辉／黯月共享的政策字节与严格 scalar 读取规则。两个真实状态 reader 使用同一实现，
 * Proxy 在反射之前拒绝，字段只读 data descriptor，既不调用 getter 也不安装能力。
 * 正整数上界、普通／null prototype 和精确 key 集合均沿用旧接受集合。
 */
import { types } from "node:util";

export const RADIANT_ECLIPSE_POLICY = "awa_radiant_eclipse_v1" as const;

export function record(value: unknown, keys: readonly string[]): Record<string, unknown> | undefined {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value)) return;
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) return;
  // 只读取 descriptor 的 value，拒绝 accessor；非枚举数据字段仍按旧规则允许。
  const fields = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(fields).length !== keys.length) return;
  const out: Record<string, unknown> = {};
  for (const key of keys) {
    const field = fields[key];
    if (!field || !("value" in field)) return;
    out[key] = field.value;
  }
  return out;
}

export function positive(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}

/**
 * 庇护的纯状态创建、严格读取、选择与玩家投影。读取返回独立数据，不暴露 live 库存；
 * N2 起效、自选与相邻夜重复目标仍按原规则拒绝。原生安装只做 JSON 复制，不能把这里
 * 的严格 reader 前移到安装入口；借用 lease、首次死亡与已支付效果继续由夜 frame 拥有。
 */
import type { ShelterState } from "@ai-werewolf-arena/game-contract";
import { RADIANT_ECLIPSE_POLICY, record, positive } from "./state-data";

export const createShelterState = (): ShelterState => ({
  policy: RADIANT_ECLIPSE_POLICY,
  lastTarget: null,
  lastDay: null,
});

/** 严格 reader 验证原精确字段形状并返回独立副本，不复制 live 实例身份或租约。 */
export function readShelterState(value: unknown): ShelterState | undefined {
  const current = record(value, ["policy", "lastTarget", "lastDay"]);
  if (
    !current ||
    current.policy !== RADIANT_ECLIPSE_POLICY ||
    (current.lastTarget !== null && !positive(current.lastTarget)) ||
    (current.lastDay !== null && (!positive(current.lastDay) || current.lastDay < 2)) ||
    (current.lastDay === null && current.lastTarget !== null)
  )
    return;
  return {
    policy: RADIANT_ECLIPSE_POLICY,
    lastTarget: current.lastTarget as number | null,
    lastDay: current.lastDay as number | null,
  };
}

/** 选择只构造 next；实际付款、uses 和原槽写入的顺序由夜阶段分别提交。 */
export function selectShelter(
  state: Readonly<ShelterState>,
  day: number,
  targetId: unknown,
  actorId: number,
  livingIds: readonly number[],
): ShelterState {
  const current = readShelterState(state);
  if (!current || !positive(day) || day < 2 || (current.lastDay !== null && day <= current.lastDay))
    throw new Error("radiant_shelter_unavailable");
  if (
    targetId !== null &&
    (!positive(targetId) ||
      targetId === actorId ||
      !livingIds.includes(targetId) ||
      (current.lastDay === day - 1 && current.lastTarget === targetId))
  )
    throw new Error("radiant_shelter_target");
  return {
    policy: RADIANT_ECLIPSE_POLICY,
    lastTarget: targetId as number | null,
    lastDay: day,
  };
}

/** 玩家投影保持原严格读取及失败前缀；它不安装或消费状态。 */
export function projectShelterState(value: unknown) {
  const state = readShelterState(value);
  if (!state) throw new Error("radiant_shelter_state_invalid");
  return state;
}

/**
 * 输入为待安装庇护状态、原能力实例或已通过选择的 next 数据；输出为安装引用、独立读取结果或原槽的字段写入。
 * 庇护夜实例的完整状态契约与实际 payload 写入。prepare 只沿用原 JSON 复制，schema 则
 * 是原严格 reader，二者接受集合不同，不能在原生安装时增加拒绝。选择／投影返回独立数据。
 * 接受行动后仍先提交已支付庇护效果、再记 uses、最后写原 payload；Object.assign callee
 * 先于 ability.state getter，写失败保留已提交前缀。借用、过期已支付效果与首死归 frame。
 */
import type { ShelterState } from "@ai-werewolf-arena/game-contract";
import { copyAbilityData, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../prepared-native-install";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { createShelterState, readShelterState, selectShelter, projectShelterState } from "./shelter-state";

/** 仅初始化安装库存，保留原 JSON 复制和 owned 返回引用，不提前执行 strict reader。 */
function installShelterState(role: RoleComponent, state: ShelterState) {
  return commitPreparedNativeAbility(role, "shelter", SHELTER_STATE_SLOT.prepare(state));
}

/** 保留 assign 查找、状态读取和逐字段写入；next 已由原 caller 完成选择。 */
function recordShelterSelection(ability: NightAbilityReadView<"shelter">, next: ShelterState): void {
  // 原顺序：查 Object.assign → 读原 ability.state → 按 next 字段顺序赋值，绝不替换槽引用。
  Object.assign(ability.state, next);
}

/** 原政策 codec 保持 JSON callee 在 state/policy 读取之前，失效仍由 scope 判定。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"shelter">): string {
  return JSON.stringify([ability.state.policy]);
}

export const SHELTER_STATE_SLOT = Object.freeze({
  create: createShelterState,
  prepare: copyAbilityData<ShelterState>,
  schema: readShelterState,
  select: selectShelter,
  project: projectShelterState,
  install: installShelterState,
  allowedWrites: Object.freeze({ recordShelterSelection }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 黯月借用各原能力 kind 的独立安装数据 reader。输入为未知 source payload、kind 与日期；
 * 输出保留原库存、政策及 fresh history 的复制形状和 own-field／Proxy 拒绝集合。
 * 此 reader 不修改 live 能力、转移授权或退回来源库存；只有庇护 reader 的导入归属改变。
 */

import type {
  SeerState,
  WitchState,
  DreamerState,
  ShelterState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { WitchSelfHealRule } from "../../../../core/domain/identity";
import { readShelterState } from "./shelter-state";

interface BorrowedStates {
  seer_check: SeerState;
  potion: WitchState;
  dream: DreamerState;
  shelter: ShelterState;
}
export type BorrowedKind = keyof BorrowedStates;
function field(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    throw new Error("eclipse_borrow_state_invalid");
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    throw new Error("eclipse_borrow_state_invalid");
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  if (!descriptor) return undefined;
  if (!("value" in descriptor)) throw new Error("eclipse_borrow_state_invalid");
  return descriptor.value;
}
function stock(value: unknown): number {
  if (value !== 0 && value !== 1) throw new Error("eclipse_borrow_stock_invalid");
  return value;
}
function optionalPolicy(value: unknown, expected: string): void {
  if (value !== undefined && value !== expected) throw new Error("eclipse_borrow_policy_invalid");
}
export function snapshotBorrowedState<K extends BorrowedKind>(
  kind: K,
  raw: unknown,
  day: number,
): BorrowedStates[K];
export function snapshotBorrowedState(
  kind: BorrowedKind,
  raw: unknown,
  day: number,
): BorrowedStates[BorrowedKind] {
  if (!Number.isSafeInteger(day) || day < 2) throw new Error("eclipse_borrow_day_invalid");
  switch (kind) {
    case "seer_check":
      optionalPolicy(field(raw, "targetPolicy"), "awa_alive_v1");
      optionalPolicy(field(raw, "actionPolicy"), "awa_required_when_legal_v1");
      return {
        targetPolicy: "awa_alive_v1",
        actionPolicy: "awa_required_when_legal_v1",
        lastTarget: null,
        lastIsWerewolf: null,
        lastResult: null,
        history: [],
      };
    case "potion":
      if (field(raw, "selfHealRule") !== WitchSelfHealRule.Disabled)
        throw new Error("eclipse_borrow_policy_invalid");
      optionalPolicy(field(raw, "knifeVisibility"), "awa_with_heal_v1");
      optionalPolicy(field(raw, "potionPolicy"), "awa_one_native_v1");
      return {
        heal: stock(field(raw, "heal")),
        poison: stock(field(raw, "poison")),
        selfHealRule: WitchSelfHealRule.Disabled,
        knifeVisibility: "awa_with_heal_v1",
        potionPolicy: "awa_one_native_v1",
        canSelfHeal: false,
        healUsedThisNight: false,
        poisonUsedThisNight: false,
      };
    case "dream": {
      if (field(raw, "protectionPolicy") !== "netease_2026_night_immunity_v1")
        throw new Error("eclipse_borrow_policy_invalid");
      const lastTarget = field(raw, "lastTarget"),
        lastDay = field(raw, "lastDay");
      if (!(
        (lastTarget === null && lastDay === null) ||
        (typeof lastTarget === "number" &&
          Number.isSafeInteger(lastTarget) &&
          lastTarget > 0 &&
          typeof lastDay === "number" &&
          Number.isSafeInteger(lastDay) &&
          lastDay >= 1 &&
          lastDay < day)
      ))
        throw new Error("eclipse_borrow_dream_state_invalid");
      return {
        lastTarget: lastTarget as number | null,
        lastDay: lastDay as number | null,
        protectionPolicy: "netease_2026_night_immunity_v1",
        history: [],
      };
    }
    case "shelter": {
      const source = readShelterState(raw);
      if (!source || (source.lastDay !== null && source.lastDay >= day))
        throw new Error("eclipse_borrow_shelter_state_invalid");
      return source;
    }
  }
}

/**
 * Opens Eclipse suppression over the exact original ability slots. Inputs are captured
 * source/target components and suppression kind; outputs are current suppression leases with read-only marker/ability references and
 * owned state changes. It never reauthorizes a changed slot or policy by restoring an unrelated
 * component.
 */
import type { EclipseSuppression } from "@ai-werewolf-arena/game-contract";

import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";

import {
  aliveLifeDescriptor,
  type AliveComponent,
  aliveLifeVersion,
} from "../../../../core/domain/components/alive";
import { captureNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightAbilityReadView } from "../abilities";
import { RADIANT_ECLIPSE_POLICY } from "./state";

export type SuppressibleAbility = NightAbilityReadView;
const invalid = Symbol("invalid_eclipse_binding");
function own(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return invalid;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return field && "value" in field ? field.value : field ? invalid : undefined;
}

function plain(value: unknown): value is object {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}
function factoryLife(value: AliveComponent | undefined): value is AliveComponent {
  if (!plain(value)) return false;
  const original = aliveLifeDescriptor(value as AliveComponent),
    actual = Object.getOwnPropertyDescriptor(value, "alive");
  return (
    !!original &&
    !!actual &&
    original.get === actual.get &&
    original.set === actual.set &&
    original.enumerable === actual.enumerable &&
    original.configurable === actual.configurable
  );
}
function canonicalSlot(value: object, key: string, expected: unknown): boolean {
  const field = Object.getOwnPropertyDescriptor(value, key);
  return (
    !!field &&
    "value" in field &&
    field.value === expected &&
    field.enumerable === true &&
    field.configurable === true &&
    field.writable === true
  );
}

/** One native instance's temporary blocker; persistent disabled belongs to its existing owner. */
export function openEclipseSuppression(
  world: World,
  actorId: number,
  ability: SuppressibleAbility,
  day: number,
) {
  const role = world.getComponent(actorId, COMPONENT.Role);
  const originalLife = world.getComponent(actorId, COMPONENT.Alive);
  if (!factoryLife(originalLife)) throw new Error("eclipse_native_suppression_invalid");
  const life = captureNightLife(world, actorId);
  const privateState = own(role, "privateState"),
    container = own(privateState, "abilities");
  const id = own(ability, "id"),
    kind = own(ability, "kind"),
    state = own(ability, "state"),
    source = own(ability, "source");
  const roleKind = own(role, "role"),
    camp = own(role, "camp");
  const identity = world.getComponent(actorId, COMPONENT.Identity);
  const identityFields = ["id", "seat", "name", "sessionId"] as const;
  const identityValues = identityFields.map((key) => own(identity, key));
  const disabled = own(ability, "disabled");
  if (
    !role ||
    !plain(ability) ||
    !plain(privateState) ||
    !plain(container) ||
    !plain(state) ||
    !plain(source) ||
    !life ||
    !Number.isSafeInteger(day) ||
    day < 2 ||
    typeof id !== "string" ||
    !id.startsWith("native:") ||
    own(container, id) !== ability ||
    own(source, "kind") !== "native" ||
    own(source, "role") !== roleKind ||
    own(ability, "nightSuppression") !== undefined ||
    typeof disabled !== "boolean" ||
    [privateState, container, kind, state, source, roleKind, camp, ...identityValues].includes(
      invalid,
    ) ||
    !identity
  )
    throw new Error("eclipse_native_suppression_invalid");
  const marker: EclipseSuppression = { policy: RADIANT_ECLIPSE_POLICY, day };
  Object.defineProperty(ability, "nightSuppression", {
    value: marker,
    writable: true,
    enumerable: true,
    configurable: true,
  });
  let closed = false;
  const sameResource = (allowFirstDeath = false) => {
    if (
      world.getComponent(actorId, COMPONENT.Role) !== role ||
      own(role, "privateState") !== privateState ||
      own(privateState, "abilities") !== container ||
      own(container, id) !== ability ||
      world.getComponent(actorId, COMPONENT.Alive) !== life.life
    )
      return false;
    const original = aliveLifeDescriptor(life.life),
      current = Object.getOwnPropertyDescriptor(life.life, "alive");
    if (
      !original ||
      !current ||
      current.get !== original.get ||
      current.set !== original.set ||
      current.configurable !== original.configurable ||
      current.enumerable !== original.enumerable
    )
      return false;
    const version = aliveLifeVersion(life.life);
    return (
      (version === life.version && life.life.alive) ||
      (allowFirstDeath && version === life.version + 1 && !life.life.alive)
    );
  };
  const sameInstance = () =>
    sameResource() &&
    plain(ability) &&
    plain(privateState) &&
    plain(container) &&
    plain(state) &&
    plain(source) &&
    own(role, "role") === roleKind &&
    own(role, "camp") === camp &&
    own(ability, "id") === id &&
    own(ability, "kind") === kind &&
    own(ability, "state") === state &&
    own(ability, "source") === source &&
    own(source, "kind") === "native" &&
    own(source, "role") === roleKind &&
    world.getComponent(actorId, COMPONENT.Identity) === identity &&
    identityFields.every((key, index) => own(identity, key) === identityValues[index]);
  return {
    actorId,
    day,
    ability,
    marker: marker as Readonly<EclipseSuppression>,
    isCurrent: () =>
      !closed &&
      sameInstance() &&
      own(ability, "disabled") === disabled &&
      canonicalSlot(ability, "nightSuppression", marker) &&
      Object.getPrototypeOf(marker) === Object.prototype &&
      Reflect.ownKeys(marker).length === 2 &&
      canonicalSlot(marker, "policy", RADIANT_ECLIPSE_POLICY) &&
      canonicalSlot(marker, "day", day),
    close(): boolean {
      if (closed) return false;
      closed = true;
      if (!sameResource(true) || own(ability, "nightSuppression") !== marker) return false;
      delete (ability as { nightSuppression?: Readonly<EclipseSuppression> }).nightSuppression;
      return true;
    },
  };
}

/**
 * Owns Radiant's pipeline night acquisition and its original terminal calls.
 * Inputs are delegated original World/events and the captured actual night day;
 * writes retain begin-before-acquisition and native close-before-publication order.
 * Normal close never suppresses acquired finally abort or its argument reads:
 * the existing frame's closed guard alone owns repeated terminal no-ops.
 * This unit never queries actors, advances phases, refunds stock or records I/O.
 */
import type { World } from "../../../../core/domain/world";
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
import { beginRadiantNight, closeRadiantNight } from "./night_frame";

export interface RadiantNightRuntime {
  readonly world: World;
  readonly events: GameEvent[];
}

export class RadiantNightUnit {
  private acquired = false;
  constructor(
    private readonly runtime: RadiantNightRuntime,
    private readonly day: number,
  ) {}

  open(): void {
    beginRadiantNight(this.runtime.world, this.day);
    this.acquired = true;
  }

  closeNormally(): void {
    closeRadiantNight(this.runtime.world, this.day, "committed", this.runtime.events);
  }

  abortIfAcquired(): void {
    if (this.acquired)
      closeRadiantNight(this.runtime.world, this.day, "aborted", this.runtime.events);
  }
}

/**
 * 负责普通夜能力授予、复制与明确转移的完整提交。输入为原 World、拥有者、安装数据与具体 statePolicy；
 * 输出为同一实际库存中的只读实例及原能力变化事实。校验、复制、来源复验和目标安装都由本模块负责。
 * 保留目标安装／发布在前、原槽删除／退役 ID／转出发布在后的顺序；异常只保留已经发生的前缀，不退款。
 * 只写原 privateState.abilities／retiredAbilityIds，不另存字典；角色 payload、生命／租约和临时抑制仍有原负责人。
 * 数据复制仍消费唯一 copyAbilityData，原接受集合不加强；这不是全部角色状态 schema 或严格复盘 codec。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import type { AbilitySource, NightAbilityKind, NightAbilityStates } from "@ai-werewolf-arena/game-contract";
import { isDeepStrictEqual } from "node:util";
import { DREAM_PROTECTION_POLICIES } from "../../../core/domain/board";
import { COMPONENT } from "../../../core/domain/components/names";
import { type EntityId, type GameEvent } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { allNightAbilities, copyAbilityData, type NightAbility, type NightAbilityReadView } from "./abilities";
import { projectNightState } from "../../observation/night-ability-projection";
import { roleOf, emit } from "./night-ability-change-runtime";

/** 安装数据只声明赠予／复制来源；日期和资源政策仍在原安装流程核对，不代表已有行动许可。 */
export interface AbilityGrant<K extends NightAbilityKind> {
  id: string;
  kind: K;
  state: NightAbilityStates[K];
  source: Extract<AbilitySource, { kind: "gift" | "copy" }>;
  startsOnDay: number;
  expiresAfterDay?: number;
  maxUses: number | null;
  sourceDisclosed?: boolean;
  activation?: "lucky" | "black_market";
}

/** 规则调用者明确提供状态／资源政策，不隐式复制目标历史或重置已付库存。 */
export function grantNightAbility<K extends NightAbilityKind>(
  world: World,
  actorId: EntityId,
  input: AbilityGrant<K>,
  events: GameEvent[],
): NightAbilityReadView<K> {
  if (input.kind === "pair_check") throw Error("ability_pair_native_only");
  if (input.source.kind !== "gift" && input.source.kind !== "copy")
    throw new Error("ability_grant_source_invalid");
  const ability = copyAbilityData({
    ...input,
    sourceDisclosed: input.sourceDisclosed ?? false,
    uses: 0,
    lastUsedDay: null,
    disabled: false,
  }) as unknown as NightAbility<K>;
  return installAbility(world, actorId, ability, events) as NightAbilityReadView<K>;
}

function installAbility(
  world: World,
  actorId: EntityId,
  ability: NightAbility,
  events: GameEvent[],
): NightAbility {
  const input = ability;
  if (input.kind === "pair_check") throw Error("ability_pair_native_only");
  if (input.kind === "role_check") roleInspectionPolicy(input.state);
  if (
    input.kind === "dream" &&
    input.state.protectionPolicy !== undefined &&
    !DREAM_PROTECTION_POLICIES.includes(input.state.protectionPolicy)
  )
    throw new Error("ability_dream_policy_invalid");
  const source = input.source;
  if (
    input.kind === "role_check" &&
    roleInspectionPolicy(input.state) === "mirror" &&
    source.kind !== "transfer" &&
    (Object.keys(input.state)
      .filter((key) => key !== "inspectionPolicy")
      .sort()
      .join() !== "history,lastDay,lastTarget,policy" ||
      input.state.lastTarget !== null ||
      input.state.lastDay !== null ||
      !Array.isArray(input.state.history) ||
      input.state.history.length !== 0 ||
      Object.keys(input.state.history).length !== 0 ||
      input.uses !== 0 ||
      input.lastUsedDay !== null ||
      input.disabled)
  )
    throw new Error("ability_mirror_initial_state_invalid");
  if (source.kind === "native") throw new Error("ability_grant_source_invalid");
  const role = roleOf(world, actorId);
  if (
    !/^[a-z][a-z0-9:_-]{0,127}$/.test(input.id) ||
    input.id.startsWith("native:") ||
    !Number.isSafeInteger(input.startsOnDay) ||
    input.startsOnDay < 1 ||
    (input.expiresAfterDay !== undefined &&
      (!Number.isSafeInteger(input.expiresAfterDay) ||
        input.expiresAfterDay < input.startsOnDay)) ||
    (input.maxUses !== null && (!Number.isSafeInteger(input.maxUses) || input.maxUses < 0))
  )
    throw new Error("ability_grant_invalid");
  roleOf(world, source.actorId);
  if (
    input.activation === "black_market" &&
    (source.kind === "copy" ||
      input.sourceDisclosed !== false ||
      input.id !== "gift:black-market" ||
      role.camp !== "good" ||
      input.startsOnDay < 2)
  )
    throw new Error("ability_black_market_policy_invalid");
  const origin =
    source.kind === "copy"
      ? allNightAbilities(roleOf(world, source.actorId)).find(
          (ability) => ability.id === source.abilityId,
        )
      : undefined;
  if (origin?.activation === "lucky" || origin?.activation === "black_market")
    throw new Error("ability_copy_lucky_not_supported");
  if (
    input.activation !== undefined &&
    (!["lucky", "black_market"].includes(input.activation) ||
      !(
        input.activation === "black_market"
          ? ["seer_check", "potion"]
          : ["seer_check", "potion", "guard"]
      ).includes(input.kind) ||
      input.maxUses !== 1)
  )
    throw new Error("ability_lucky_policy_invalid");
  if (
    allNightAbilities(role).some((ability) => ability.id === input.id) ||
    (
      ((role.privateState as { readonly retiredAbilityIds?: unknown }).retiredAbilityIds ??
        []) as string[]
    ).includes(input.id)
  )
    throw new Error("ability_id_duplicate");
  if (
    source.kind !== "gift" &&
    !allNightAbilities(roleOf(world, source.actorId)).some(
      (ability) => ability.id === source.abilityId && ability.kind === input.kind,
    )
  )
    throw new Error("ability_source_mismatch");
  // 原字典赋值已发生后才发布；push／时钟／来源克隆失败都保留已安装实例。
  const stored = ((role.privateState as { abilities?: Record<string, NightAbility> }).abilities ??=
    {}) as Record<string, NightAbility>;
  stored[ability.id] = ability;
  emit(events, actorId, ability, "granted");
  return ability;
}

/** 先验证／安装目标，再移除原 owner；保留计数、原夜时点与中途发布失败前缀。 */
export function transferNightAbility<K extends NightAbilityKind>(
  world: World,
  fromId: EntityId,
  toId: EntityId,
  id: string,
  targetId: string,
  events: GameEvent[],
  options: {
    kind: K;
    statePolicy: (state: Readonly<NightAbilityStates[K]>) => NightAbilityStates[K];
    sourceDisclosed?: boolean;
  },
): void {
  if (fromId === toId) throw new Error("ability_transfer_same_owner");
  const source = roleOf(world, fromId),
    ability = allNightAbilities(source).find((ability) => ability.id === id);
  if (!ability) throw new Error("ability_instance_missing");
  if (ability.kind === "pair_check") throw Error("ability_pair_native_only");
  if (!options || options.kind !== ability.kind || typeof options.statePolicy !== "function")
    throw new Error("ability_transfer_policy_required");
  const black = ability.activation === "black_market",
    target = roleOf(world, toId),
    fromLife = captureNightLife(world, fromId),
    toLife = captureNightLife(world, toId),
    originalState = ability.state,
    originalSource = ability.source,
    sourcePrivate = source.privateState,
    targetPrivate = target.privateState,
    originalRole = source.role,
    targetRole = target.role;
  if (
    black &&
    (!fromLife ||
      !toLife ||
      source.camp !== "good" ||
      target.camp !== "good" ||
      targetId !== id ||
      options.sourceDisclosed === true)
  )
    throw new Error("ability_black_market_transfer_invalid");
  const before = black
    ? copyAbilityData({
        id: ability.id,
        kind: ability.kind,
        source: ability.source,
        startsOnDay: ability.startsOnDay,
        expiresAfterDay: ability.expiresAfterDay,
        maxUses: ability.maxUses,
        uses: ability.uses,
        lastUsedDay: ability.lastUsedDay,
        disabled: ability.disabled,
        deathExpired: ability.deathExpired,
        activation: ability.activation,
        sourceDisclosed: ability.sourceDisclosed,
        state: projectNightState(ability),
      })
    : undefined;
  // 政策回调消费独立数据；黑市随后复验原组件／生命／槽及规范化内容，不用复制结果恢复许可。
  const targetState = copyAbilityData(
    options.statePolicy(
      copyAbilityData(black ? projectNightState(ability) : ability.state) as NightAbilityStates[K],
    ),
  );
  if (
    black &&
    (options.kind !== ability.kind ||
      options.sourceDisclosed === true ||
      world.getComponent(fromId, COMPONENT.Role) !== source ||
      source.role !== originalRole ||
      source.camp !== "good" ||
      source.privateState !== sourcePrivate ||
      world.getComponent(toId, COMPONENT.Role) !== target ||
      target.role !== targetRole ||
      target.camp !== "good" ||
      target.privateState !== targetPrivate ||
      !livingNightLife(world, fromLife!) ||
      !livingNightLife(world, toLife!) ||
      allNightAbilities(source).find((candidate) => candidate.id === id) !== ability ||
      ability.state !== originalState ||
      ability.source !== originalSource ||
      !isDeepStrictEqual(
        before,
        copyAbilityData({
          id: ability.id,
          kind: ability.kind,
          source: ability.source,
          startsOnDay: ability.startsOnDay,
          expiresAfterDay: ability.expiresAfterDay,
          maxUses: ability.maxUses,
          uses: ability.uses,
          lastUsedDay: ability.lastUsedDay,
          disabled: ability.disabled,
          deathExpired: ability.deathExpired,
          activation: ability.activation,
          sourceDisclosed: ability.sourceDisclosed,
          state: projectNightState(ability),
        }),
      ))
  )
    throw new Error("ability_black_market_transfer_revoked");
  if (
    (ability.activation === "lucky" || ability.activation === "black_market") &&
    !isDeepStrictEqual(targetState, black ? projectNightState(ability) : ability.state)
  )
    throw new Error("ability_transfer_lucky_state_changed");
  // 转移保持资源；seer_check 明确政策可重置知识，role_check 保留完整历史，其他政策不能补库存。
  if (
    ability.kind === "guard" &&
    (targetState as NightAbilityStates["guard"]).lastTarget !== ability.state.lastTarget
  )
    throw new Error("ability_transfer_resources_changed");
  if (
    ability.kind === "dream" &&
    ((targetState as NightAbilityStates["dream"]).lastTarget !== ability.state.lastTarget ||
      (targetState as NightAbilityStates["dream"]).lastDay !== ability.state.lastDay ||
      (targetState as NightAbilityStates["dream"]).protectionPolicy !==
        ability.state.protectionPolicy)
  )
    throw new Error("ability_transfer_resources_changed");
  if (
    ability.kind === "potion" &&
    [
      "heal",
      "poison",
      "selfHealRule",
      "canSelfHeal",
      "healUsedThisNight",
      "poisonUsedThisNight",
    ].some(
      (key) =>
        (targetState as unknown as Record<string, unknown>)[key] !==
        (ability.state as unknown as Record<string, unknown>)[key],
    )
  )
    throw new Error("ability_transfer_resources_changed");
  if (ability.kind === "role_check" && !isDeepStrictEqual(targetState, ability.state))
    throw new Error("ability_transfer_role_inspection_history_changed");
  const received = copyAbilityData({
    ...ability,
    state: targetState,
    id: targetId,
    sourceDisclosed: options.sourceDisclosed ?? false,
    source: { kind: "transfer", actorId: fromId, abilityId: id },
  }) as NightAbility;
  // 目标安装与其发布成功后才移除源；delete、退休数组 push 和转出发布各有已写前缀，不回滚。
  installAbility(world, toId, received, events);
  delete (
    (source.privateState as { readonly abilities?: unknown }).abilities as Record<
      string,
      NightAbility
    >
  )[id];
  (
    ((source.privateState as { retiredAbilityIds?: string[] }).retiredAbilityIds ??= []) as string[]
  ).push(id);
  emit(events, fromId, ability, "transferred_out");
}
